import type {UsageMetadata} from '../types/ai.js';
import {aggregateUsage} from './usageAggregation.js';

describe('aggregateUsage', () => {
  it('sums usage from multiple rounds', () => {
    const usage1: UsageMetadata = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
    const usage2: UsageMetadata = {inputTokens: 23, outputTokens: 3, totalTokens: 26};
    const usage3: UsageMetadata = {inputTokens: 37, outputTokens: 5, totalTokens: 42};

    const result = aggregateUsage([usage1, usage2, usage3]);

    expect(result).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('skips undefined rounds', () => {
    const usage1: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
    const usage2: UsageMetadata = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

    const result = aggregateUsage([usage1, undefined, usage2]);

    expect(result).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('returns undefined when no rounds report usage', () => {
    const result = aggregateUsage([]);

    expect(result).toBeUndefined();
  });

  it('returns undefined when all rounds are undefined', () => {
    const result = aggregateUsage([undefined, undefined]);

    expect(result).toBeUndefined();
  });

  it('returns single usage when only one round reports', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};

    const result = aggregateUsage([undefined, usage]);

    expect(result).toEqual(usage);
  });
});

