export function aggregateUsage(rounds: Array<UsageMetadata | undefined>): UsageMetadata | undefined {
  const reported = rounds.filter((usage): usage is UsageMetadata => usage !== undefined);

  if (reported.length === 0) {
    return undefined;
  }

  const aggregated = reported.reduce(
    (acc, usage) => ({
      inputTokens: acc.inputTokens + usage.inputTokens,
      outputTokens: acc.outputTokens + usage.outputTokens,
      totalTokens: acc.totalTokens + usage.totalTokens,
    }),
    {inputTokens: 0, outputTokens: 0, totalTokens: 0}
  );

  return aggregated;
}

