export function aggregateUsage(rounds: Array<UsageMetadata | undefined>): UsageMetadata | undefined {
  const reported = rounds.filter((usage): usage is UsageMetadata => usage !== undefined);

  if (reported.length === 0) {
    return undefined;
  }

  return {
    inputTokens: reported.reduce((sum, usage) => sum + usage.inputTokens, 0),
    outputTokens: reported.reduce((sum, usage) => sum + usage.outputTokens, 0),
    totalTokens: reported.reduce((sum, usage) => sum + usage.totalTokens, 0),
  };
}
